q(5,3,'Concentration','A solution contains 0.20 mol in a final volume of 0.50 L. Find molar concentration.',.4,'mol/L','Use final solution volume, not solvent volume.', ['c = n/V','c = 0.20/0.50'],S('book-chemistry-p64-r03',{n:.2,V:.5}));
