q(5,5,'Dilution','Dilute 0.10 L of a 2.0 mol/L solution to 0.50 L without losing solute. Find final concentration.',.4,'mol/L','The amount of solute stays constant.', ['c₁V₁ = c₂V₂','c₂ = 2.0×0.10/0.50'],S('book-chemistry-p64-r05',{'c₁':2,'V₁':.1,'c₂':A,'V₂':.5},{compareSides:true}));
q(5,6,'Particle count','Find the number of molecules in 0.25 mol, using N_A=6.02214076×10²³ mol⁻¹.',1.50553519e23,'molecules','Avogadro’s constant links amount to particle count.', ['N = n N_A','N = 0.25×6.02214076×10²³'],S('book-chemistry-p64-r01',{n:.25,N_A:6.02214076e23}));
q(5,7,'Hydrogen-ion activity','Hydrogen-ion activity relative to its standard state is 10⁻³. Find pH.',3,'','The logarithm takes a dimensionless activity.', ['pH = −log₁₀(aH)','pH = −log₁₀(10⁻³)'],S('book-chemistry-p68-r01',{a_H:.001}));
