q(5,9,'Molar gas volume','An ideal gas occupies 0.0498 m³ and contains 2.00 mol. Find molar volume in litres per mole.',24.9,'L/mol','Divide total volume by amount, then convert cubic metres to litres.', ['Vm = V/n = 0.0498/2 m³/mol','Vm = 0.0249×1000 L/mol'],S('book-chemistry-p64-r07',{V:.0498,n:2},{outputScale:1000}));
