q(5,11,'Conjugate acid and base','At a temperature with Kw=10⁻¹⁴, an acid has Ka=10⁻⁵. Find Kb of its conjugate base.',1e-9,'','Ka and Kb refer to a conjugate pair at the same temperature.', ['Ka Kb = Kw','Kb = 10⁻¹⁴/10⁻⁵'],S('book-chemistry-p67-r07',{K_a:1e-5,K_b:A},{side:0,expected:1e-14}));
q(5,12,'Temperature-dependent neutrality','At a temperature with pKw=12.8, find the pH of a neutral aqueous solution.',6.4,'','Neutrality means equal hydrogen and hydroxide activities; pH need not be 7.', ['pHneutral = pKw/2','pHneutral = 12.8/2'],S('book-chemistry-p68-r06',{pK_w:12.8}));
q(5,13,'Buffer ratio','For a buffer with pKa=4.76 and conjugate-base/acid activity ratio 10, estimate pH.',5.76,'','Use the activity ratio and the logarithmic buffer relation.', ['pH = pKa + log₁₀(aA/aHA)','pH = 4.76 + log₁₀(10)'],S('book-chemistry-p68-r08',{pK_a:4.76,a_A:.1,a_HA:.01}));
