q(6,3,'Conductance','Find conductance of a 20 Ω resistor.',.05,'S','Conductance is the reciprocal of resistance.', ['G = 1/R','G = 1/20'],S('book-c6-p79-r05',{R:20}));
q(6,4,'Resistor power','A resistor has 24 V across 12 Ω. Find dissipated power.',48,'W','Use voltage squared divided by resistance.', ['P = U²/R','P = 24²/12'],S('book-c6-p81-r08',{U:24,R:12}));
