q(6,6,'Temperature correction','A conductor is 10 Ω at its reference temperature. For α=0.004 K⁻¹ and a 50 K rise, estimate resistance.',12,'Ω','Use the temperature change relative to the resistance reference.', ['R = R₀(1+αΔT)','R = 10(1+0.004×50)'],S('book-c6-p79-r04',{'R₀':10,'α':.004,'ΔT':50}));
