q(7,2,'Emitter current','A transistor carries IC=10 mA and IB=0.10 mA. Find emitter current.',10.1,'mA','Apply current continuity at the transistor.', ['IE = IB+IC','IE = 0.10+10'],S('book-c7-p103-r01',{I_B:.0001,I_C:.01},{outputScale:1000}));
q(7,3,'Voltage gain magnitude','Input amplitude is 0.20 V and output amplitude is 2.0 V. Find voltage gain magnitude.',10,'','This question asks for magnitude, without an inversion sign.', ['Av = |Vout/Vin|','Av = |2.0/0.20|'],S('book-c7-p103-r04',{V_out:2,V_in:.2}));
