q(7,5,'Negative feedback','An amplifier has open-loop gain 100 and negative-feedback factor 0.09. Find closed-loop gain.',10,'','Use the negative-feedback denominator 1+βA.', ['Acl = A/(1+βA)','Acl = 100/(1+0.09×100)'],S('book-c7-p104-r01',{A:100,'β':.09}));
q(7,6,'Inverting amplifier','An ideal linear op-amp has Rin=10 kΩ, Rf=40 kΩ and Vin=0.50 V. Supplies permit the output. Find Vout.',-2,'V','Keep the inversion minus sign.', ['Vout = −Rf Vin/Rin','Vout = −40×0.50/10'],S('book-c7-p107-r03',{R_f:40000,V_in:.5,R_in:10000}));
