q(7,10,'LC resonance','Find ideal resonance frequency for L=10 mH and C=1 µF.',1/(2*pi*Math.sqrt(.01e-6)),'Hz','Use henries and farads in 1/(2π√LC).', ['LC = 0.01×10⁻⁶ s²','f₀ = 1/(2π√LC)'],S('book-c7-p116-r01',{L:.01,C:1e-6}));
