q(8,5,'Half-wave average','An ideal half-wave rectifier receives a sinusoid with peak 100 V and a resistive load. Find mean output voltage.',100/pi,'V','Average over the entire AC period, including the blocked half-cycle.', ['Vdc = Vm/π','Vdc = 100/π'],S('book-c8-p122-r01',{V_m:100}));
